// One-time differential test (CONTRACT T05): querylog.js must reach
// the same decision and source per correlation key `pid:serial:client/port`
// as the ucode data plane it replaces (abfm.logparse + abfm.stats, with the
// 10 s pending TTL), over the dnsmasq fixtures and the `log read` fixtures.
// The expectations were generated by scripts/hosttools/querylog-differential.sh
// while that ucode existed; they are now the regression oracle.
import assert from 'node:assert/strict';
import test from 'node:test';
import { readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { ql, fixture, fixtureText, replyFromLogread } from './querylog-load.mjs';

// Intentional differences, by expectation file and key, with the reason.
const DIFFERENCES = {
  'logread-restart': {
    // querylog.js resets correlation on `started, version` (serials restart with
    // dnsmasq), so the query in flight is "no answer" at once; the daemon
    // kept it pending until its TTL, which this capture never reaches.
    '1:37:10.0.2.2/38032': { domain: 'err.example.test', decision: 'no-answer', source: null }
  }
};

const dir = fileURLToPath(new URL('../fixtures/logread/differential/', import.meta.url));
const files = readdirSync(dir).filter((f) => f.endsWith('.expected.json')).sort();

test('differential expectations exist for every captured fixture', () => {
  assert.deepEqual(files, [
    'dnsmasq-addnhosts.expected.json', 'dnsmasq-restart-heartbeat.expected.json', 'dnsmasq-servers.expected.json',
    'logread-addnhosts.expected.json', 'logread-logd-after.expected.json', 'logread-logd-before.expected.json',
    'logread-restart.expected.json', 'logread-servers.expected.json'
  ]);
});

for (const file of files) {
  const name = file.replace('.expected.json', '');
  test(`differential: ${name}`, () => {
    const expected = { ...fixture(`differential/${file}`), ...(DIFFERENCES[name] ?? {}) };
    const reply = name.startsWith('dnsmasq-')
      ? replyFromLogread(fixtureText(`dnsmasq/${name.slice('dnsmasq-'.length)}.log`))
      : fixture(`${name.slice('logread-'.length)}.json`);
    const st = ql.create({ local_domains: ['lan'] });
    ql.ingest(st, reply);
    const actual = {};
    for (const r of ql.rows(st, { show_router: true })) {
      // row keys are `epoch:pid:serial:client/port`; the epoch counts dnsmasq restarts
      const key = r.key.slice(r.key.indexOf(':') + 1);
      assert.equal(actual[key], undefined, `key ${key} seen once`);
      actual[key] = { domain: r.domain, decision: r.decision, source: r.source };
    }
    assert.deepEqual(actual, expected);
  });
}
